impl Document {
    pub(crate) fn compare_mc_function_data_ref_set(
        &self,
        _other: &Document,
        a: &McFunctionDataRefSet,
        b: &McFunctionDataRefSet,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        let list_a = a.get_flat_map_entry_refs();
        let list_b = b.get_flat_map_entry_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: FLAT_MAP_ENTRY_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.FLAT_MAP_ENTRY_REFS[{index}] mismatch"));
            }
        }
        let list_a = a.get_mc_data_instance_refs();
        let list_b = b.get_mc_data_instance_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MC_DATA_INSTANCE_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.MC_DATA_INSTANCE_REFS[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_rpt_component(
        &self,
        other: &Document,
        a: &RptComponent,
        b: &RptComponent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_mc_data_assignments();
        let list_b = b.get_mc_data_assignments();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MC_DATA_ASSIGNMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.role_based_mc_data_assignments.get(*x).ok_or_else(|| {
                format!("{path}.MC_DATA_ASSIGNMENTS[{index}]: id not found in own arena")
            })?;
            let y = other
                .role_based_mc_data_assignments
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.MC_DATA_ASSIGNMENTS[{index}]: id not found in other arena")
                })?;
            self.compare_role_based_mc_data_assignment(
                other,
                x,
                y,
                &format!("{path}.MC_DATA_ASSIGNMENTS[{index}]"),
            )?;
        }
        if a.get_rp_impl_policy() != b.get_rp_impl_policy() {
            return Err(format!("{path}: RP_IMPL_POLICY mismatch"));
        }
        let list_a = a.get_rpt_executable_entities();
        let list_b = b.get_rpt_executable_entities();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: RPT_EXECUTABLE_ENTITIES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.rpt_executable_entitys.get(*x).ok_or_else(|| {
                format!("{path}.RPT_EXECUTABLE_ENTITIES[{index}]: id not found in own arena")
            })?;
            let y = other.rpt_executable_entitys.get(*y).ok_or_else(|| {
                format!("{path}.RPT_EXECUTABLE_ENTITIES[{index}]: id not found in other arena")
            })?;
            self.compare_rpt_executable_entity(
                other,
                x,
                y,
                &format!("{path}.RPT_EXECUTABLE_ENTITIES[{index}]"),
            )?;
        }
        Ok(())
    }

    pub(crate) fn compare_rpt_executable_entity(
        &self,
        other: &Document,
        a: &RptExecutableEntity,
        b: &RptExecutableEntity,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_rpt_executable_entity_events();
        let list_b = b.get_rpt_executable_entity_events();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: RPT_EXECUTABLE_ENTITY_EVENTS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.rpt_executable_entity_events.get(*x).ok_or_else(|| {
                format!("{path}.RPT_EXECUTABLE_ENTITY_EVENTS[{index}]: id not found in own arena")
            })?;
            let y = other.rpt_executable_entity_events.get(*y).ok_or_else(|| {
                format!("{path}.RPT_EXECUTABLE_ENTITY_EVENTS[{index}]: id not found in other arena")
            })?;
            self.compare_rpt_executable_entity_event(
                other,
                x,
                y,
                &format!("{path}.RPT_EXECUTABLE_ENTITY_EVENTS[{index}]"),
            )?;
        }
        let list_a = a.get_rpt_reads();
        let list_b = b.get_rpt_reads();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: RPT_READS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .role_based_mc_data_assignments
                .get(*x)
                .ok_or_else(|| format!("{path}.RPT_READS[{index}]: id not found in own arena"))?;
            let y = other
                .role_based_mc_data_assignments
                .get(*y)
                .ok_or_else(|| format!("{path}.RPT_READS[{index}]: id not found in other arena"))?;
            self.compare_role_based_mc_data_assignment(
                other,
                x,
                y,
                &format!("{path}.RPT_READS[{index}]"),
            )?;
        }
        let list_a = a.get_rpt_writes();
        let list_b = b.get_rpt_writes();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: RPT_WRITES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .role_based_mc_data_assignments
                .get(*x)
                .ok_or_else(|| format!("{path}.RPT_WRITES[{index}]: id not found in own arena"))?;
            let y = other
                .role_based_mc_data_assignments
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.RPT_WRITES[{index}]: id not found in other arena")
                })?;
            self.compare_role_based_mc_data_assignment(
                other,
                x,
                y,
                &format!("{path}.RPT_WRITES[{index}]"),
            )?;
        }
        if a.get_symbol() != b.get_symbol() {
            return Err(format!("{path}: SYMBOL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_rpt_executable_entity_event(
        &self,
        other: &Document,
        a: &RptExecutableEntityEvent,
        b: &RptExecutableEntityEvent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_execution_context_refs();
        let list_b = b.get_execution_context_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: EXECUTION_CONTEXT_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.EXECUTION_CONTEXT_REFS[{index}] mismatch"));
            }
        }
        let list_a = a.get_mc_data_assignments();
        let list_b = b.get_mc_data_assignments();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MC_DATA_ASSIGNMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.role_based_mc_data_assignments.get(*x).ok_or_else(|| {
                format!("{path}.MC_DATA_ASSIGNMENTS[{index}]: id not found in own arena")
            })?;
            let y = other
                .role_based_mc_data_assignments
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.MC_DATA_ASSIGNMENTS[{index}]: id not found in other arena")
                })?;
            self.compare_role_based_mc_data_assignment(
                other,
                x,
                y,
                &format!("{path}.MC_DATA_ASSIGNMENTS[{index}]"),
            )?;
        }
        if a.get_rpt_event_id() != b.get_rpt_event_id() {
            return Err(format!("{path}: RPT_EVENT_ID mismatch"));
        }
        if a.get_rpt_executable_entity_properties() != b.get_rpt_executable_entity_properties() {
            return Err(format!("{path}: RPT_EXECUTABLE_ENTITY_PROPERTIES mismatch"));
        }
        if a.get_rpt_impl_policy() != b.get_rpt_impl_policy() {
            return Err(format!("{path}: RPT_IMPL_POLICY mismatch"));
        }
        let list_a = a.get_rpt_service_point_post_refs();
        let list_b = b.get_rpt_service_point_post_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: RPT_SERVICE_POINT_POST_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.RPT_SERVICE_POINT_POST_REFS[{index}] mismatch"
                ));
            }
        }
        let list_a = a.get_rpt_service_point_pre_refs();
        let list_b = b.get_rpt_service_point_pre_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: RPT_SERVICE_POINT_PRE_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.RPT_SERVICE_POINT_PRE_REFS[{index}] mismatch"
                ));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_rpt_execution_context(
        &self,
        other: &Document,
        a: &RptExecutionContext,
        b: &RptExecutionContext,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_rpt_service_point(
        &self,
        other: &Document,
        a: &RptServicePoint,
        b: &RptServicePoint,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_service_id() != b.get_service_id() {
            return Err(format!("{path}: SERVICE_ID mismatch"));
        }
        if a.get_symbol() != b.get_symbol() {
            return Err(format!("{path}: SYMBOL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_rpt_support_data(
        &self,
        other: &Document,
        a: &RptSupportData,
        b: &RptSupportData,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        let list_a = a.get_execution_contexts();
        let list_b = b.get_execution_contexts();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: EXECUTION_CONTEXTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.rpt_execution_contexts.get(*x).ok_or_else(|| {
                format!("{path}.EXECUTION_CONTEXTS[{index}]: id not found in own arena")
            })?;
            let y = other.rpt_execution_contexts.get(*y).ok_or_else(|| {
                format!("{path}.EXECUTION_CONTEXTS[{index}]: id not found in other arena")
            })?;
            self.compare_rpt_execution_context(
                other,
                x,
                y,
                &format!("{path}.EXECUTION_CONTEXTS[{index}]"),
            )?;
        }
        let list_a = a.get_rpt_components();
        let list_b = b.get_rpt_components();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: RPT_COMPONENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.rpt_components.get(*x).ok_or_else(|| {
                format!("{path}.RPT_COMPONENTS[{index}]: id not found in own arena")
            })?;
            let y = other.rpt_components.get(*y).ok_or_else(|| {
                format!("{path}.RPT_COMPONENTS[{index}]: id not found in other arena")
            })?;
            self.compare_rpt_component(other, x, y, &format!("{path}.RPT_COMPONENTS[{index}]"))?;
        }
        let list_a = a.get_rpt_service_points();
        let list_b = b.get_rpt_service_points();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: RPT_SERVICE_POINTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.rpt_service_points.get(*x).ok_or_else(|| {
                format!("{path}.RPT_SERVICE_POINTS[{index}]: id not found in own arena")
            })?;
            let y = other.rpt_service_points.get(*y).ok_or_else(|| {
                format!("{path}.RPT_SERVICE_POINTS[{index}]: id not found in other arena")
            })?;
            self.compare_rpt_service_point(
                other,
                x,
                y,
                &format!("{path}.RPT_SERVICE_POINTS[{index}]"),
            )?;
        }
        Ok(())
    }

    pub(crate) fn compare_rpt_sw_prototyping_access(
        &self,
        _other: &Document,
        a: &RptSwPrototypingAccess,
        b: &RptSwPrototypingAccess,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_rpt_hook_access() != b.get_rpt_hook_access() {
            return Err(format!("{path}: RPT_HOOK_ACCESS mismatch"));
        }
        if a.get_rpt_read_access() != b.get_rpt_read_access() {
            return Err(format!("{path}: RPT_READ_ACCESS mismatch"));
        }
        if a.get_rpt_write_access() != b.get_rpt_write_access() {
            return Err(format!("{path}: RPT_WRITE_ACCESS mismatch"));
        }
        Ok(())
    }
}
